package com.logistics.gateway;
import io.jsonwebtoken.JwtException;
import org.springframework.cloud.gateway.filter.*;import org.springframework.core.Ordered;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.server.ServerWebExchange;import reactor.core.publisher.Mono;
@Component public class JwtGatewayFilter implements GlobalFilter,Ordered {private final JwtTokenService tokens;public JwtGatewayFilter(JwtTokenService t){tokens=t;}public int getOrder(){return -100;}public Mono<Void> filter(ServerWebExchange ex,GatewayFilterChain chain){var p=ex.getRequest().getPath().value();if(ex.getRequest().getMethod()==HttpMethod.OPTIONS||p.equals("/actuator/health")||p.equals("/actuator/prometheus")||p.startsWith("/api/auth"))return chain.filter(ex);var h=ex.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);if(h==null||!h.startsWith("Bearer "))return reject(ex,"Missing bearer token");try{tokens.parse(h.substring(7));return chain.filter(ex);}catch(JwtException|IllegalArgumentException e){return reject(ex,"Invalid or expired token");}}private Mono<Void> reject(ServerWebExchange ex,String message){ex.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);return ex.getResponse().writeWith(Mono.just(ex.getResponse().bufferFactory().wrap(message.getBytes())));}}
